import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const ZoomOutImagem: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const dur = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const src = String(anim.params?.src ?? "");
  const rawZoom = Number(anim.params?.zoom);
  const startScale = Number.isFinite(rawZoom) && rawZoom > 1 ? Math.min(rawZoom, 4) : 1.6;

  // Fast-then-slow: a steep ease-out curve over the whole layer.
  const scale = interpolate(f, [0, dur], [startScale, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.05, 0.75, 0.1, 1),
  });

  if (!src) {
    const minSide = Math.min(frame.width, frame.height);
    return (
      <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center" }}>
        <div
          style={{
            width: frame.width * 0.88,
            height: frame.height * 0.88,
            borderRadius: minSide * 0.02,
            backgroundColor: COLORS.vellum,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${scale})`,
          }}
        >
          <div
            style={{
              color: dark ? COLORS.mutedOnDark : COLORS.mutedOnLight,
              fontWeight: FONTS.bodyWeight,
              fontSize: minSide * 0.045,
              textAlign: "center",
              padding: minSide * 0.04,
            }}
          >
            Sem imagem
          </div>
        </div>
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, overflow: "hidden" }}>
      <Img
        src={src}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          transform: `scale(${scale})`,
          transformOrigin: "50% 50%",
        }}
      />
    </AbsoluteFill>
  );
};

export default ZoomOutImagem;

