import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const ZoomOutImpacto: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const src = String(anim.params?.src ?? "");
  const rawZoom = Number(anim.params?.zoomFrom);
  const zoomFrom = Number.isFinite(rawZoom) && rawZoom > 1 ? Math.min(rawZoom, 4) : 1.6;

  const dur = Math.max(2, Math.round((anim.end - anim.start) * fps));
  // Fast punch-out over ~0.35s (never more than 30% of the layer), then a slow settle.
  const fastEnd = Math.max(1, Math.min(Math.round(0.35 * fps), Math.floor(dur * 0.3)));
  const mid = 1 + (zoomFrom - 1) * 0.2;

  const scale = interpolate(f, [0, fastEnd, dur], [zoomFrom, mid, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const opacity = interpolate(f, [0, Math.max(1, Math.round(fps * 0.12))], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  return (
    <AbsoluteFill style={{ overflow: "hidden", opacity }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${scale})`,
          transformOrigin: "50% 50%",
        }}
      >
        {src ? (
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
        ) : (
          <AbsoluteFill
            style={{
              alignItems: "center",
              justifyContent: "center",
              backgroundColor: "rgba(255,255,255,0.06)",
              border: `${Math.max(2, Math.round(Math.min(frame.width, frame.height) * 0.004))}px dashed ${muted}`,
              boxSizing: "border-box",
            }}
          >
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontStyle: "italic",
                textTransform: "uppercase",
                color: muted,
                fontSize: Math.round(Math.min(frame.width, frame.height) * 0.06),
                textAlign: "center",
                padding: "0 6%",
              }}
            >
              Sem imagem
            </div>
          </AbsoluteFill>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ZoomOutImpacto;

import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const ZoomOutImagem: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const t = useCurrentFrame();
  const len = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const src = String(anim.params?.src ?? "");
  const zoomRaw = Number(anim.params?.zoom);
  const zoom = Number.isFinite(zoomRaw) && zoomRaw > 1 ? Math.min(zoomRaw, 4) : 1.8;

  // Fast pull-back at the start, then a long slow drift towards 1.
  const scale = interpolate(t, [0, len], [zoom, 1], {
    easing: Easing.bezier(0.12, 0.9, 0.25, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  if (!src) {
    const short = Math.min(frame.width, frame.height);
    return (
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", fontFamily: FONTS.body }}>
        <div
          style={{
            width: frame.width * 0.8,
            height: frame.height * 0.8,
            borderRadius: short * 0.03,
            border: `${Math.max(2, short * 0.004)}px dashed ${dark ? COLORS.mutedOnDark : COLORS.mutedOnLight}`,
            backgroundColor: "rgba(255,255,255,.06)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${scale / zoom + (1 - 1 / zoom)})`,
          }}
        >
          <span
            style={{
              color: dark ? COLORS.mutedOnDark : COLORS.mutedOnLight,
              fontSize: short * 0.05,
              fontWeight: FONTS.bodyWeight,
            }}
          >
            Imagem
          </span>
        </div>
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Img
        src={src}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          transform: `scale(${scale})`,
          transformOrigin: "50% 50%",
        }}
      />
    </AbsoluteFill>
  );
};

export default ZoomOutImagem;
